  `id` int(11) NOT NULL AUTO_INCREMENT,
  `case_id` int(11) NOT NULL,
  `name` varchar(250) NOT NULL,
  `opd_number` varchar(20) NOT NULL,
  `sex` varchar(50) NOT NULL,
  `age_year` varchar(20) NOT NULL,
  `age_month` varchar(20) NOT NULL,
  `age_day` varchar(20) NOT NULL,
  `demise` varchar(100) NOT NULL,
  `species` varchar(200) NOT NULL,
  `breed` varchar(200) NOT NULL,
  `sample_type` varchar(200) NOT NULL DEFAULT '-',
  `weight` varchar(20) NOT NULL,
  `dead_date` varchar(20) NOT NULL,
  `collect_date` varchar(20) NOT NULL,
  `keep_method` varchar(200) NOT NULL,
  `speed` varchar(100) NOT NULL DEFAULT 'ไม่เร่งด่วน',
  `medical_record` varchar(512) NOT NULL DEFAULT 'ไม่ทราบ',
  `dosage_record` varchar(512) NOT NULL DEFAULT 'ไม่ทราบ',
  `sample_inspection` varchar(100) NOT NULL,
  `state` int(11) NOT NULL DEFAULT 0,
  `status` int(11) NOT NULL DEFAULT 1,
  `updater` int(11) NOT NULL,
  `room` int(11) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1904 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------
-- Records of sample_registration
-- ----------------------------

